// 点击追踪
document.addEventListener("click", (event) => {
  const target = event.target as HTMLElement
  const tagName = target.tagName || ""
  const id = target.id || ""
  let className = ""
  try {
    className = typeof target.className === "string" 
      ? target.className 
      : (target.getAttribute ? (target.getAttribute("class") || "") : "")
  } catch (e) {
    className = ""
  }
  const text = target.textContent?.substring(0, 50) || ""
  
  const safeClassName = String(className || "")
  const firstClass = safeClassName ? safeClassName.split(" ")[0] : ""
  
  Sentry.addBreadcrumb({
    category: "ui.click",
    message: `Click: ${tagName}${id ? "#" + id : ""}${firstClass ? "." + firstClass : ""}`,
    level: "info",
    data: { tagName, id, className: firstClass, text }
  })
}, true)

